1	/** Ask the extension to copy text to the OS clipboard (fallback path). */
2	export function parentClipboardWrite(text: string) {
3	  try {
4	    window.parent.postMessage(
5	      { type: 'vscode-iframe-clipboard-copy', text },
6	      '*'
7	    );
8	  } catch (_err) {
9	    void 0;
10	  }
11	}
