13	/** Copy helper that prefers navigator.clipboard and falls back to the bridge. */
14	export async function writeClipboardViaBridge(text: string): Promise<boolean> {
15	  try {
16	    await navigator.clipboard.writeText(text);
17	    return true;
18	  } catch {
19	    parentClipboardWrite(text);
20	    return false;
21	  }
22	}
