11	/**
12	 * Play a sound file.  In the Tauri desktop app we use AudioContext (Web
13	 * Audio API) because `new Audio()` registers with macOS NowPlaying /
14	 * MediaRemote, triggering an "access Apple Music" TCC prompt.  In the
15	 * browser the standard HTMLAudioElement works fine.
16	 */
17	export async function playSound(url: string): Promise<void> {
18	  if ('__TAURI_INTERNALS__' in window) {
19	    const ctx = new AudioContext();
20	    try {
21	      const res = await fetch(url);
22	      const buf = await res.arrayBuffer();
23	      const audio = await ctx.decodeAudioData(buf);
24	      const src = ctx.createBufferSource();
25	      src.buffer = audio;
26	      src.connect(ctx.destination);
27	      src.start();
28	      await new Promise<void>((resolve) => {
29	        src.onended = () => resolve();
30	      });
31	    } finally {
32	      await ctx.close();
33	    }
34	  } else {
35	    const audio = new Audio(url);
36	    await audio.play();
37	  }
38	}
