40	export function formatFileSize(bytes: bigint | null | undefined): string {
41	  if (!bytes) return '';
42	  const num = Number(bytes);
43	  if (num < 1024) return `${num} B`;
44	  if (num < 1024 * 1024) return `${(num / 1024).toFixed(1)} KB`;
45	  return `${(num / (1024 * 1024)).toFixed(1)} MB`;
46	}
